CREATE TABLE IF NOT EXISTS "farm_tasks" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"planting_id" uuid REFERENCES "plantings"("id") ON DELETE set null,"zone_id" uuid REFERENCES "farm_zones"("id") ON DELETE set null,"task_type" text NOT NULL,"title" text NOT NULL,"description" text NOT NULL,"priority" text DEFAULT 'normal' NOT NULL,"due_date" date,"source" text DEFAULT 'generated' NOT NULL,"fingerprint" text NOT NULL UNIQUE,"status" text DEFAULT 'pending' NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"completed_at" timestamp with time zone);
CREATE INDEX IF NOT EXISTS "farm_tasks_status_idx" ON "farm_tasks" ("status");
